import {
  index,
  integer,
  primaryKey,
  sqliteTable,
  text,
} from 'drizzle-orm/sqlite-core'

// Cloudflare D1 (SQLite). Ids are the original WordPress ids, inserted explicitly by the
// data migration; `INTEGER PRIMARY KEY` makes them the rowid, so rows created later
// would still be numbered automatically. Dates are stored as Unix time in milliseconds.
//
// Foreign keys have no ON DELETE CASCADE on purpose: D1 cannot turn foreign keys off
// during a migration, so a table rebuild generated by drizzle-kit (DROP TABLE of the
// parent) would silently delete every link row. Without CASCADE it fails instead; such
// migrations need every `PRAGMA foreign_keys=OFF/ON` replaced with
// `PRAGMA defer_foreign_keys = ON/OFF` (see README; test/migrations.test.ts checks).

export const authors = sqliteTable('authors', {
  id: integer('id').primaryKey(),
  slug: text('slug').notNull().unique(),
  name: text('name').notNull(),
  description: text('description'),
})

export const categories = sqliteTable('categories', {
  id: integer('id').primaryKey(),
  slug: text('slug').notNull().unique(),
  name: text('name').notNull(),
  description: text('description'),
})

export const tags = sqliteTable('tags', {
  id: integer('id').primaryKey(),
  slug: text('slug').notNull().unique(),
  name: text('name').notNull(),
  description: text('description'),
})

export const posts = sqliteTable(
  'posts',
  {
    id: integer('id').primaryKey(),
    /**
     * WordPress `post_name`: lowercase, with non-ASCII characters
     * percent-encoded (e.g. `%e3%81%82`). Slugs longer than 191 characters
     * were truncated by the previous MySQL schema (VARCHAR(191)).
     */
    slug: text('slug').notNull().unique(),
    title: text('title').notNull(),
    /** `title` as compared by the search (toSearchText), computed by the data migration. */
    searchTitle: text('search_title').notNull(),
    /** Rendered HTML (`content.rendered`). */
    content: text('content').notNull(),
    /** Plain-text lead of `content`, precomputed by the data migration. */
    excerpt: text('excerpt').notNull().default(''),
    /** `jetpack_featured_media_url` */
    featuredMediaUrl: text('featured_media_url'),
    authorId: integer('author_id')
      .notNull()
      .references(() => authors.id),
    /** `date_gmt` */
    createdAt: integer('created_at', { mode: 'timestamp_ms' }).notNull(),
    /** `modified_gmt` */
    updatedAt: integer('updated_at', { mode: 'timestamp_ms' }).notNull(),
  },
  (t) => [
    // Newest-first listings read this index backwards and stop after one page. It also
    // holds the search form of the title, so title search scans the index instead of the
    // rows (which carry the article HTML).
    index('posts_created_at_id_search_title_idx').on(
      t.createdAt,
      t.id,
      t.searchTitle,
    ),
    index('posts_author_id_created_at_id_idx').on(
      t.authorId,
      t.createdAt,
      t.id,
    ),
  ],
)

// The link tables repeat the post's created_at, so a category's or tag's newest posts are
// read in order from one index instead of sorting all of its posts on every page. The
// archive is frozen; the data migration writes both copies.

export const postCategories = sqliteTable(
  'post_categories',
  {
    postId: integer('post_id')
      .notNull()
      .references(() => posts.id),
    categoryId: integer('category_id')
      .notNull()
      .references(() => categories.id),
    /** Copy of `posts.created_at`. */
    postCreatedAt: integer('post_created_at', {
      mode: 'timestamp_ms',
    }).notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.postId, t.categoryId] }),
    index('post_categories_category_id_post_created_at_post_id_idx').on(
      t.categoryId,
      t.postCreatedAt,
      t.postId,
    ),
  ],
)

export const postTags = sqliteTable(
  'post_tags',
  {
    postId: integer('post_id')
      .notNull()
      .references(() => posts.id),
    tagId: integer('tag_id')
      .notNull()
      .references(() => tags.id),
    /** Copy of `posts.created_at`. */
    postCreatedAt: integer('post_created_at', {
      mode: 'timestamp_ms',
    }).notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.postId, t.tagId] }),
    index('post_tags_tag_id_post_created_at_post_id_idx').on(
      t.tagId,
      t.postCreatedAt,
      t.postId,
    ),
  ],
)
